# pascal_triangle :: 3
def pascal_triangle(n):
    rows = [[1] * (i + 1) for i in range(n)]
    for i in range(2, n):
        for j in range(1, i):
            rows[i][j] = rows[i-1][j-1] + rows[i-1][j]
    return rows

if __name__ == '__main__':
    print(pascal_triangle(3))

